package ru.main.explorer;
import android.animation.*;import android.app.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
/** Real Android animator/Canvas states. No physical Camera2 claim. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SpatialMotionTest {
 ActivityController<Activity> controller;Activity activity;FrameLayout root;MapView map;
 @Before public void setup(){MotionTest.durationScale(1);controller=Robolectric.buildActivity(Activity.class).setup();activity=controller.get();root=new FrameLayout(activity);activity.setContentView(root);map=new MapView(activity);map.online=false;root.addView(map,new FrameLayout.LayoutParams(512,512));map.layout(0,0,512,512);map.cx=128;map.cy=128;map.zoom=4;map.follow=false;}
 @After public void cleanup(){map.close();controller.pause().stop().destroy();MotionTest.durationScale(1);WalkService.running=false;}
 void seek(long ms){assertNotNull(map.viewportMotion);map.viewportMotion.setCurrentPlayTime(ms);}
 Store.Photo photo(long id,double lon){return new PhotoSelectionTest().photo(id,lon);}
 ArrayList<Store.Photo> photos(Store.Photo... p){return new ArrayList<>(Arrays.asList(p));}
 void ageCards(long ms){for(MapView.CardMotion card:map.cards.values())card.since-=ms;}
 @Test public void zoomHasRealFractionalIntermediateAndExactFinal(){map.changeZoom(1);seek(90);assertTrue(map.displayZoom>4&&map.displayZoom<5);assertTrue(map.viewportFraction>1);map.viewportMotion.end();assertEquals(5,map.zoom);assertEquals(1,map.viewportFraction,0);assertNull(map.viewportMotion);assertEquals(128,map.cx,0);}
 @Test public void panHasIntermediateCoordinatesAndExactDestination(){map.moveViewport(MapView.x(12),MapView.y(20),5);seek(110);assertTrue(map.centerLongitude()>0&&map.centerLongitude()<12);assertTrue(map.centerLatitude()>0&&map.centerLatitude()<20);map.viewportMotion.end();assertEquals(12,map.centerLongitude(),1e-10);assertEquals(20,map.centerLatitude(),1e-10);}
 @Test public void locateUsesRealFixAndCanBeInterrupted(){android.location.Location fix=new android.location.Location("gps");fix.setLatitude(20);fix.setLongitude(12);fix.setAccuracy(5);map.setCurrent(fix,false);map.locate();seek(80);assertTrue(map.follow);assertNotEquals(12,map.centerLongitude(),1e-8);map.viewportMotion.end();assertEquals(12,map.centerLongitude(),1e-10);assertEquals(20,map.centerLatitude(),1e-10);}
 @Test public void touchCancelsWithoutCoordinateOrScaleJump(){map.moveViewport(132,130,6);seek(90);double x=map.cx,y=map.cy,z=map.displayZoom;float fraction=map.viewportFraction;MotionEvent event=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,20,30,0);map.onTouchEvent(event);event.recycle();assertNull(map.viewportMotion);assertEquals(x,map.cx,0);assertEquals(y,map.cy,0);assertEquals(z,map.displayZoom,1e-7);assertEquals(fraction,map.viewportFraction,0);}
 @Test public void repeatedZoomAccumulatesAndDetachStopsOldCallback(){map.changeZoom(1);seek(60);map.changeZoom(1);assertEquals(6,map.targetZoom);map.viewportMotion.end();assertEquals(6,map.zoom);map.moveViewport(140,140,7);seek(60);double x=map.cx;root.removeView(map);assertNull(map.viewportMotion);shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(1));assertEquals(x,map.cx,0);}
 @Test public void disabledAnimationHasNoPendingViewportOrCards(){MotionTest.durationScale(0);map.moveViewport(140,130,8);assertNull(map.viewportMotion);assertEquals(140,map.cx,0);assertEquals(8,map.zoom);map.cx=128;map.cy=128;map.setPhotos(photos(photo(1,0)));assertEquals(1,map.animatedPhotos().get(0).opacity,0);}
 @Test public void cardsEnterMoveExitByStableIdentityAndNeverClickGhost(){map.zoom=16;map.setPhotos(photos(photo(1,0),photo(2,0)));ArrayList<PhotoGroups.Group> start=map.animatedPhotos();assertEquals(0,start.get(1).opacity,0);ageCards(80);PhotoGroups.Group middle=map.animatedPhotos().get(1);PhotoGroups.Group target=map.photoGroups().get(1);assertTrue(middle.opacity>0&&middle.opacity<1);assertTrue(Math.abs(middle.y-middle.anchorY)<Math.abs(target.y-target.anchorY));ageCards(400);map.animatedPhotos();map.setPhotos(photos(photo(2,0)));ArrayList<PhotoGroups.Group> changed=map.animatedPhotos();assertEquals(2,changed.size());assertTrue(map.cards.get(1L).exiting);assertFalse(map.cards.get(2L).exiting);long[] tapped={0};map.setPhotoTapListener(p->tapped[0]=p.get(0).id);PhotoGroups.Group live=null;for(PhotoGroups.Group g:changed)if(!g.exiting)live=g;assertNotNull(live);assertTrue(map.tapPhotos(live.x,live.y));assertEquals(2,tapped[0]);map.setPhotos(photos());map.animatedPhotos();assertFalse(map.tapPhotos(live.x,live.y));ageCards(400);assertTrue(map.animatedPhotos().isEmpty());assertTrue(map.cards.isEmpty());}
 @Test public void fractionalProjectionAndCardHitTestAgree(){map.zoom=16;map.viewportFraction=1.4f;map.setPhotos(photos(photo(7,.001)));map.animatedPhotos();ageCards(400);PhotoGroups.Group g=map.animatedPhotos().get(0);assertEquals(256+(map.screenX(.001)-256)*1.4f,g.anchorX,.01);long[] id={0};map.setPhotoTapListener(p->id[0]=p.get(0).id);assertTrue(map.tapPhotos(g.x,g.y));assertEquals(7,id[0]);assertFalse(map.tapPhotos(g.x+30,g.y+30));}
 @Test public void pinchIsContinuousAnchoredAndCancelEndsGesture(){CameraPinchTest events=new CameraPinchTest();double before=map.zoom;events.event(map,MotionEvent.ACTION_DOWN,1,200,10);events.event(map,MotionEvent.ACTION_POINTER_DOWN|256,2,200,30);events.event(map,MotionEvent.ACTION_MOVE,2,300,70);events.event(map,MotionEvent.ACTION_MOVE,2,450,110);assertTrue(map.displayZoom>before);assertNull(map.viewportMotion);assertFalse(map.follow);double z=map.displayZoom;events.event(map,MotionEvent.ACTION_CANCEL,2,450,130);events.event(map,MotionEvent.ACTION_DOWN,1,200,150);events.event(map,MotionEvent.ACTION_MOVE,1,500,170);events.event(map,MotionEvent.ACTION_UP,1,500,190);assertEquals(z,map.displayZoom,1e-6);}
 @Test public void menuUsesActualButtonScreenPivotAndSettles(){Button button=new Button(activity);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(60,50);p.leftMargin=400;p.topMargin=100;root.addView(button,p);button.layout(400,100,460,150);AlertDialog dialog=new AtlasUi.DialogBuilder(activity,button).setTitle("Menu").setItems(new String[]{"One"},null).show();shadowOf(Looper.getMainLooper()).idle();View decor=AtlasUi.anchorPanel(dialog);assertEquals(-1,dialog.getWindow().getAttributes().height);int[] a=new int[2],d=new int[2];button.getLocationOnScreen(a);decor.getLocationOnScreen(d);assertEquals(a[0]+30-d[0],decor.getPivotX(),.01);assertEquals(a[1]+25-d[1],decor.getPivotY(),.01);AtlasMotion.anchorNow(decor,button);assertNotNull(AtlasMotion.running.get(decor));AtlasMotion.running.get(decor).setCurrentPlayTime(60);assertTrue(decor.getScaleX()>.08f&&decor.getScaleX()<1);AtlasMotion.running.get(decor).end();assertEquals(1,decor.getScaleX(),.001);dialog.dismiss();}
 @Test public void noRouteRebuildRequestsDuringViewportAnimation()throws Exception{map.asyncRendering=true;map.moveViewport(132,130,5);java.lang.reflect.Field desired=MapView.class.getDeclaredField("desiredX");desired.setAccessible(true);desired.setDouble(map,123);for(int t:new int[]{30,90,180,300}){seek(t);map.requestFrame();assertEquals(123,desired.getDouble(map),0);}map.stopViewport();}
 @Test public void cameraFlipNeverMakesHardwareReadyAndPauseCancels()throws Exception{ActivityController<CameraActivity> c=Robolectric.buildActivity(CameraActivity.class).setup();CameraActivity a=c.get();CameraControlsTest access=new CameraControlsTest();access.set(a,"active",true);access.set(a,"ready",true);a.switchCamera();assertEquals(false,access.get(a,"ready"));assertEquals(true,access.get(a,"switching"));assertFalse(a.cameraControlsEditable());a.finishSwitch();assertEquals(true,access.get(a,"switching"));View preview=(View)access.get(a,"preview");assertNotNull(AtlasMotion.running.get(preview));AtlasMotion.running.get(preview).setCurrentPlayTime(60);assertTrue(preview.getRotationY()>0&&preview.getRotationY()<88);int generation=a.cameraGeneration();a.onPause();assertEquals(false,access.get(a,"switching"));assertEquals(0,preview.getRotationY(),0);shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(1));assertEquals(generation+1,a.cameraGeneration());assertEquals(false,access.get(a,"ready"));c.destroy();}
 @Test public void walkReactionOnlyFollowsActualStateChanges()throws Exception{WalkService.running=false;ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup();MainActivity a=c.get();java.lang.reflect.Field field=MainActivity.class.getDeclaredField("stats");field.setAccessible(true);View stats=(View)field.get(a);a.refresh();assertEquals(1,stats.getScaleX(),0);WalkService.running=true;a.refresh();assertEquals(.88f,stats.getScaleX(),.001);a.refresh();assertEquals(.88f,stats.getScaleX(),.001);WalkService.running=false;a.refresh();assertEquals(1.10f,stats.getScaleX(),.001);c.pause().stop().destroy();}
 @Test public void realMenuSurfaceRendersFromAnchorWithoutWindowClipping()throws Exception{Button button=new Button(activity);FrameLayout.LayoutParams anchorParams=new FrameLayout.LayoutParams(60,50);anchorParams.leftMargin=430;anchorParams.topMargin=600;root.addView(button,anchorParams);button.layout(430,600,490,650);AlertDialog dialog=new AtlasUi.DialogBuilder(activity,button).setTitle("MapNotes").setItems(new String[]{"Map","Photos","Walks"},null).show();shadowOf(Looper.getMainLooper()).idle();View decor=dialog.getWindow().getDecorView(),panel=AtlasUi.anchorPanel(dialog);decor.measure(View.MeasureSpec.makeMeasureSpec(512,1073741824),View.MeasureSpec.makeMeasureSpec(700,1073741824));decor.layout(0,0,512,700);AtlasMotion.anchorNow(panel,button);Bitmap strip=Bitmap.createBitmap(512*5,700,Bitmap.Config.ARGB_8888);Canvas output=new Canvas(strip);Bitmap previous=null;for(int i=0;i<5;i++){AtlasMotion.running.get(panel).setCurrentPlayTime(i*75);Bitmap frame=Bitmap.createBitmap(512,700,Bitmap.Config.ARGB_8888);decor.draw(new Canvas(frame));if(previous!=null)assertFalse(frame.sameAs(previous));output.drawBitmap(frame,i*512,0,null);previous=frame;}File dir=new File("build/motion-123");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"menu-filmstrip.png"))){assertTrue(strip.compress(Bitmap.CompressFormat.PNG,100,out));}dialog.dismiss();assertNull(AtlasMotion.running.get(panel));}
 @Test public void realCanvasFilmstripHasDifferentIntermediateFrames()throws Exception{map.cx=MapView.x(25);map.cy=MapView.y(35);map.zoom=2;map.changeZoom(2);Bitmap strip=Bitmap.createBitmap(512*6,512,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(strip);int[] times={0,40,90,160,280,480};Bitmap previous=null;for(int i=0;i<times.length;i++){if(map.viewportMotion!=null)map.viewportMotion.setCurrentPlayTime(times[i]);Bitmap frame=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);map.draw(new Canvas(frame));if(previous!=null)assertFalse("Actual rendered frame must change",frame.sameAs(previous));canvas.drawBitmap(frame,i*512,0,null);previous=frame;}File dir=new File("build/motion-123");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"viewport-filmstrip.png"))){assertTrue(strip.compress(Bitmap.CompressFormat.PNG,100,out));}assertEquals(4,map.zoom);}
}
